/* ============================================================
   ゲノム解析学「📖 学習」の要点テキスト
   ------------------------------------------------------------
   1回（デッキ）＝1オブジェクト。deck は questions.js の
   slideRefs[].deck と完全一致させる（問題・スライドの紐付けキー）。

     deck       必須。"01" など2桁
     hidden     任意。true にすると「学習」の授業回一覧に出さない
                （出題範囲外の回。問題側の根拠スライド表示には影響しない）
     group      任意。学習トップでまとめるフォルダ名（例："用語解説"）。
                書かない章はフォルダに入れず単独のカードで並ぶ
     title      任意。章名の上書き（既定は slideRefs の name）
     intro      任意。その回を1〜2文で要約
     sections[] 任意。{ heading, body, slides:[頁番号] }
                body の改行は "\n"、箇条書きは行頭に "・"
     keySlides  任意。章の冒頭に出す代表図のページ番号

   章名・問題数・スライドの総ページ数はアプリが questions.js から
   導出するので、ここには書かない（重複を持たせない）。
   書き方の指針は materials/genome/学習コンテンツ作成方針.md。
   ============================================================ */

