        body:
          "==リアルタイムPCR（quantitative PCR、qPCR）は、蛍光検出のできるサーマルサイクラーで、増幅と同時にサイクルごとの産物量を測定していく方法==である。==増え方の曲線を観察し、蛍光が一定のしきい値を超えるサイクル数（Ct値）から、反応前の鋳型量を逆算する==。\n" +
          "\n" +
          "・==鋳型が多いほど早くしきい値に達する＝Ct値が小さい==。==Ct値と初期鋳型量の対数は直線関係==になるので、これを検量線として定量する\n" +
          "・重要なのは「==増幅が指数的に進んでいる途中==」で測ること。==サイクルを重ねると反応が飽和（プラトー）して、初期量の違いが産物量に反映されなくなる==ため\n" +
          "・用途は、==アレイやRNA-seqで見つけた発現差の確認、臨床サンプルにおける特定DNA配列のコピー数解析、突然変異やSNPのスクリーニング==など\n" +
          "\n" +
          "試験ではこう出る：==2020・2021・2022・2023の4年連続==で「定量的PCR（リアルタイムPCR）について不適切なのはどれか」→==〈最終温度サイクル終了後（2020年度は「最終サイクル後」）に増幅産物を定量する〉==が出ている。==これはエンドポイント（終点）測定の説明であって、リアルタイム定量の考え方に真っ向から反する==。「==サイクルごとに測る==」「==指数増幅の途中の情報を使う==」というリアルタイムPCRの本質を、そのまま裏返した選択肢である。2020年度Q82では、正しい記述の側に==〈増幅産物は短い方が好ましい〉〈単一の増幅産物が得られる条件が必要である〉〈増幅産物の定量は、一般に蛍光を指標とする〉〈反応前の反応液中の鋳型量を推定するのに利用する〉==の4つが並んでいた。==4つとも次のブロックの内容そのものなので、定量PCRの要件のチェックリストとして使える==。",
